// Lee la caducidad real del certificado TLS y las Core Web Vitals de campo
// (CrUX, vía PageSpeed Insights) de una web, y las guarda en metrics_daily
// con upsert (site_id, day). Solo field data: si Google no tiene tráfico
// real de esta web, se guarda null en vez de una estimación de laboratorio.
//
// El sandbox del task runner no expone globals como URL: hay que pedirlos
// con require() igual que los módulos, y además añadirlos a
// NODE_FUNCTION_ALLOW_BUILTIN en n8n-task-runners.json ("crypto,tls,url").
const tls = require('tls');
const { URL } = require('url');

function getCertExpiry(hostname, port = 443, timeout = 8000) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (!settled) {
        settled = true;
        resolve(value);
      }
    };
    const socket = tls.connect(port, hostname, { servername: hostname, timeout }, () => {
      const cert = socket.getPeerCertificate();
      socket.end();
      finish({ date: cert && cert.valid_to ? new Date(cert.valid_to).toISOString() : null, error: null });
    });
    socket.on('error', (err) => finish({ date: null, error: err && err.code ? err.code : (err && err.message ? err.message : 'tls_error') }));
    socket.on('timeout', () => { socket.destroy(); finish({ date: null, error: 'tls_timeout' }); });
  });
}

const site = $input.item.json;
const hostname = new URL(site.url).hostname;

const sslResult = await getCertExpiry(hostname);
const sslExpiresAt = sslResult.date;
const tlsError = sslResult.error;
const hasPagespeedKey = Boolean($env.PAGESPEED_API_KEY);

let lcpMs = null;
let inpMs = null;
let cls = null;
let screenshotDataUri = null;
let labPerformanceScore = null;
let labLcpMs = null;
let labCls = null;
let labTbtMs = null;
let psiStatus = null;
let psiError = null;
let hasLoadingExperience = false;
let hasPageMetrics = false;
let hasOriginMetrics = false;
let pageMetricsKeys = [];
let originMetricsKeys = [];
let hasFinalScreenshot = false;
let screenshotMime = null;

try {
  const psi = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://www.googleapis.com/pagespeedonline/v5/runPagespeed',
    qs: { url: site.url, strategy: 'mobile', key: $env.PAGESPEED_API_KEY },
    json: true,
    timeout: 30000,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true,
  });
  psiStatus = psi.statusCode;
  if (psi.body && psi.body.error) {
    psiError = psi.body.error.message || psi.body.error.status || 'psi_error';
  }
  hasLoadingExperience = Boolean(psi.body && psi.body.loadingExperience);
  const pageMetrics = psi.body && psi.body.loadingExperience && psi.body.loadingExperience.metrics;
  const originMetrics = psi.body && psi.body.originLoadingExperience && psi.body.originLoadingExperience.metrics;
  hasPageMetrics = Boolean(pageMetrics);
  hasOriginMetrics = Boolean(originMetrics);
  pageMetricsKeys = pageMetrics ? Object.keys(pageMetrics) : [];
  originMetricsKeys = originMetrics ? Object.keys(originMetrics) : [];
  const metrics = pageMetrics || originMetrics;
  if (metrics) {
    if (metrics.LARGEST_CONTENTFUL_PAINT_MS) lcpMs = metrics.LARGEST_CONTENTFUL_PAINT_MS.percentile;
    if (metrics.INTERACTION_TO_NEXT_PAINT) inpMs = metrics.INTERACTION_TO_NEXT_PAINT.percentile;
    if (metrics.CUMULATIVE_LAYOUT_SHIFT_SCORE) cls = metrics.CUMULATIVE_LAYOUT_SHIFT_SCORE.percentile / 100;
  }
  // Prueba de laboratorio (Lighthouse, una carga simulada). Va a columnas
  // lab_* propias y la interfaz la etiqueta como simulada: nunca rellena el
  // hueco de las métricas de campo de arriba (§3 del SPEC).
  const lighthouse = psi.body && psi.body.lighthouseResult;
  if (lighthouse) {
    const perf = lighthouse.categories && lighthouse.categories.performance;
    if (perf && typeof perf.score === 'number') labPerformanceScore = Math.round(perf.score * 100);
    const audit = (id) => lighthouse.audits && lighthouse.audits[id] && lighthouse.audits[id].numericValue;
    if (typeof audit('largest-contentful-paint') === 'number') labLcpMs = Math.round(audit('largest-contentful-paint'));
    if (typeof audit('cumulative-layout-shift') === 'number') labCls = Math.round(audit('cumulative-layout-shift') * 1000) / 1000;
    if (typeof audit('total-blocking-time') === 'number') labTbtMs = Math.round(audit('total-blocking-time'));
  }
  // La captura sí sale de la ejecución de laboratorio de Lighthouse: es una
  // imagen de la portada, no una métrica, así que no hay dato que falsear.
  const screenshot = psi.body && psi.body.lighthouseResult && psi.body.lighthouseResult.audits
    && psi.body.lighthouseResult.audits['final-screenshot'];
  if (screenshot && screenshot.details && typeof screenshot.details.data === 'string') {
    screenshotDataUri = screenshot.details.data;
    hasFinalScreenshot = true;
    finalScreenshotType = screenshot.details.type || null;
  }
} catch (err) {
  psiError = (err && err.message) ? err.message.slice(0, 300) : 'psi_request_failed';
  // Sin datos de PSI en esta ejecución: se queda en null, nunca un valor inventado.
}

const today = new Date().toISOString().slice(0, 10);

// Captura de la portada → Storage (bucket privado site-screenshots). Si falla,
// se queda la anterior con su fecha: el panel muestra cuándo se tomó.
let screenshotSaved = false;
// Motivo legible si no se guarda la captura: en qué paso falló y qué
// respondió el servidor. Nunca incluye claves.
let screenshotError = null;
let screenshotStep = null;
const screenshotMatch = screenshotDataUri && screenshotDataUri.match(/^data:(image\/(?:jpeg|png|webp));base64,(.+)$/);
if (screenshotMatch) {
  try {
    screenshotStep = 'decodificar imagen (Buffer)';
    const BufferImpl = typeof Buffer !== 'undefined' ? Buffer : require('buffer').Buffer;
    const path = `${site.id}/latest.jpg`;
    screenshotStep = 'subir a Storage';
    const upload = await this.helpers.httpRequest({
      method: 'POST',
      url: `${$env.SUPABASE_URL}/storage/v1/object/site-screenshots/${path}`,
      headers: {
        apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
        'Content-Type': screenshotMatch[1],
        'x-upsert': 'true',
      },
      body: BufferImpl.from(screenshotMatch[2], 'base64'),
      json: false,
      timeout: 20000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (upload.statusCode < 200 || upload.statusCode >= 300) {
      const uploadBody = typeof upload.body === 'string' ? upload.body : JSON.stringify(upload.body);
      throw new Error(`HTTP ${upload.statusCode} ${String(uploadBody).slice(0, 300)}`);
    }
    screenshotStep = 'guardar ruta en sites';
    const patch = await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${$env.SUPABASE_URL}/rest/v1/sites`,
      qs: { id: `eq.${site.id}` },
      headers: {
        apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
        Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal',
      },
      body: { screenshot_path: path, screenshot_taken_at: new Date().toISOString() },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (patch.statusCode < 200 || patch.statusCode >= 300) {
      throw new Error(`HTTP ${patch.statusCode} ${JSON.stringify(patch.body).slice(0, 300)}`);
    }
    screenshotSaved = true;
  } catch (err) {
    // Sin captura nueva hoy; no bloquea el guardado de SSL y CWV.
    screenshotError = `${screenshotStep}: ${err.message}`;
  }
} else if (screenshotDataUri) {
  screenshotError = `formato de captura no reconocido: ${screenshotDataUri.slice(0, 40)}`;
}

await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.SUPABASE_URL}/rest/v1/metrics_daily`,
  qs: { on_conflict: 'site_id,day' },
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'resolution=merge-duplicates,return=minimal',
  },
  body: {
    site_id: site.id,
    day: today,
    ssl_expires_at: sslExpiresAt,
    lcp_ms: lcpMs,
    inp_ms: inpMs,
    cls,
    lab_performance_score: labPerformanceScore,
    lab_lcp_ms: labLcpMs,
    lab_cls: labCls,
    lab_tbt_ms: labTbtMs,
  },
  json: true,
});

return {
  json: {
    site_id: site.id,
    site_name: site.name,
    site_url: site.url,
    ssl_expires_at: sslExpiresAt,
    lcp_ms: lcpMs,
    inp_ms: inpMs,
    cls,
    lab_performance_score: labPerformanceScore,
    lab_lcp_ms: labLcpMs,
    lab_cls: labCls,
    lab_tbt_ms: labTbtMs,
    screenshot_saved: screenshotSaved,
    screenshot_error: screenshotError,
    has_pagespeed_key: hasPagespeedKey,
    psi_status: psiStatus,
    psi_error: psiError,
    has_loading_experience: hasLoadingExperience,
    has_page_metrics: hasPageMetrics,
    has_origin_metrics: hasOriginMetrics,
    page_metrics_keys: pageMetricsKeys,
    origin_metrics_keys: originMetricsKeys,
    has_final_screenshot: hasFinalScreenshot,
    final_screenshot_type: finalScreenshotType,
    tls_error: tlsError,
  },
};

// Abre o cierra la incidencia informativa de "SSL a punto de caducar",
// mismo patrón que la incidencia de caída del recolector de uptime.
const SSL_EXPIRING_WARNING_DAYS = 14;

const item = $('Comprobar SSL y CWV').item.json;
const baseUrl = $env.SUPABASE_URL;
const headers = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
};

let action = 'none';
let message = null;

if (item.ssl_expires_at) {
  const daysLeft = Math.floor((new Date(item.ssl_expires_at).getTime() - Date.now()) / 86400000);

  const openIncidents = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/rest/v1/incidents`,
    qs: {
      site_id: `eq.${item.site_id}`,
      kind: 'eq.ssl_expiring',
      resolved_at: 'is.null',
      select: 'id,opened_at',
      order: 'opened_at.desc',
      limit: '1',
    },
    headers,
    json: true,
  });
  const openIncident = openIncidents[0] ?? null;

  if (daysLeft <= SSL_EXPIRING_WARNING_DAYS && !openIncident) {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/rest/v1/incidents`,
      headers: { ...headers, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
      body: {
        site_id: item.site_id,
        kind: 'ssl_expiring',
        severity: 'info',
        detail: `Caduca el ${item.ssl_expires_at}`,
      },
      json: true,
    });
    action = 'opened';
    message = `⚠️ El SSL de ${item.site_name} caduca en ${daysLeft} días.\n${item.site_url}`;
  } else if (daysLeft > SSL_EXPIRING_WARNING_DAYS && openIncident) {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${baseUrl}/rest/v1/incidents`,
      qs: { id: `eq.${openIncident.id}` },
      headers: { ...headers, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
      body: { resolved_at: new Date().toISOString() },
      json: true,
    });
    action = 'closed';
    message = `✅ El SSL de ${item.site_name} se ha renovado.\n${item.site_url}`;
  }
}

return { json: { action, message } };
